function shell(){ui.innerHTML=`<div id="shade" class="home-shade"></div><header class="topbar"><div class="brand"><i class="brandmark"></i>CHIP ARENA <span class="badge">PROTOTYPE</span></div><div class="top-meta" id="connection"></div></header><main id="menus" class="menus"></main><div id="hud" class="hud"></div><div id="sandbox"></div><div id="player-board"></div><div id="notice" class="notice hidden" role="status"></div><dialog id="network-report" class="network-report"><h2>Connection report</h2><p>Take this report from both players while the lag is happening.</p><pre id="network-report-text"></pre><div class="actions">${btn('copy-network-report','Copy report',true)}${btn('close-network-report','Close')}</div></dialog><div class="bottom-line" id="footer"><span>BUILD 0.1 &nbsp; / &nbsp; DESKTOP CONTROLS</span><span>11 ARENAS &nbsp; · &nbsp; 2–8 PILOTS</span></div>`;}
function notice(message:string){const el=document.querySelector('#notice')!;el.textContent=message;el.classList.remove('hidden');noticeUntil=performance.now()+6500;}
function panel(title:string,body:string,wide=false,eyebrow='CHIP ARENA'){return `<section class="panel ${wide?'wide':''}"><div class="panel-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1></div>${screen!=='game'?'<button class="close" data-action="home" aria-label="Close">×</button>':''}</div>${body}</section>`;}
function classOptions(){return `<div class="options">${(Object.keys(CLASS_INFO)as ClassId[]).map(c=>`<button data-class="${c}" class="class-option ${chosenClass===c?'active':''}"><span class="class-symbol">${c==='ranged'?'⊕':c==='magic'?'ϟ':'╱'}</span><strong>${CLASS_INFO[c].name}</strong><small>${c==='ranged'?'PRECISION & PRESSURE':c==='magic'?'ELEMENTS & CONTROL':'CLOSE & PERSONAL'}</small></button>`).join('')}</div>`;}
function chipButton(chipId:string){return chipCard(CHIPS.find(c=>c.id===chipId)!,getMe()?.chips[chipId]||0);}
const introOptions=()=>`<label class="settings-row">Skip player intros <input id="skip-intros" type="checkbox" ${pref.skipIntros?'checked':''}/></label><p class="fine">Intros play once per match, before the opening countdown.</p>`;
const draftOptions=()=>`<label class="settings-row" for="draftChoices">Chip choices per draft <select id="draftChoices">${Array.from({length:12},(_,n)=>`<option value="${n+1}" ${draftChoices===n+1?'selected':''}>${n+1}${n===5?' (default)':''}</option>`).join('')}</select></label><label class="settings-row" for="draftSeconds">Chip selection timer <span><input id="draftSeconds" class="input timer-input" type="number" min="5" max="120" step="1" value="${draftSeconds}"/> seconds</span></label><p class="fine">5–120 seconds per player. Also applies to specialization selection.</p>`;
function matchOptions(lobby=false){const map=lobby?mapId(state.options.map):selectedMap,bots=lobby?state.players.filter(p=>p.bot).length:screen==='practice'?practiceBots:roomBots,max=lobby?CONFIG.maxPlayers-state.players.filter(p=>!p.bot).length:7,diff=lobby?state.options.botDifficulty||'normal':difficulty,disabled=lobby&&roomOwner!==id?'disabled':'';
 return `<div class="match-options"><label class="field" for="arena-map">ARENA</label><select id="arena-map" ${disabled}>${MAPS.map(m=>`<option value="${m.id}" ${map===m.id?'selected':''}>${m.name}</option>`).join('')}</select><p class="fine map-description">${arenaMap(map).tag}</p><div class="row"><div><label class="field" for="bot-count">BOTS</label><select id="bot-count" ${disabled}>${Array.from({length:max+1},(_,n)=>n).filter(n=>screen!=='practice'||n>0).map(n=>`<option value="${n}" ${n===bots?'selected':''}>${n}${n===1?' bot':' bots'}</option>`).join('')}</select></div><div><label class="field" for="bot-difficulty">BOT DIFFICULTY</label><select id="bot-difficulty" ${disabled}>${['dummy','easy','normal','hard'].map(d=>`<option value="${d}" ${diff===d?'selected':''}>${d[0].toUpperCase()+d.slice(1)}</option>`).join('')}</select></div></div><p class="fine">Up to 8 pilots total. Bots use player slots.${lobby?' Only the room owner can change these settings.':''}</p></div>`;
}
function previewMap(){if(mode!=='local'||!['home','practice','create'].includes(screen))return;sim.configureLobby({map:selectedMap});state=sim.snapshot();}
async function createDesktopRoom(){if(nativeBusy)return;const attempt=++hostRequest;nativeBusy=true;connectionError='';drawMenu(true);try{const address=await window.arenaDesktop!.hostRoom!(hostOnline);if(attempt!==hostRequest||screen!=='create')return;inviteBase=address.invite;connect(address.endpoint,false,'');}catch(e){if(attempt===hostRequest){connectionError=e instanceof Error?e.message:'Could not start hosting.';notice(connectionError);}}finally{if(attempt===hostRequest){nativeBusy=false;drawMenu(true);}}}
async function joinDesktopRoom(raw:string){if(nativeBusy)return;inviteCode=raw;const attempt=++hostRequest;nativeBusy=true;connectionError='';drawMenu(true);try{const address=await window.arenaDesktop!.resolveRoom!(raw);if(attempt!==hostRequest||screen!=='join')return;inviteBase=address.invite;connect(address.endpoint,true,address.code!);}catch(e){if(attempt===hostRequest){connectionError=e instanceof Error?e.message:'Could not find the room.';notice(connectionError);}}finally{if(attempt===hostRequest){nativeBusy=false;drawMenu(true);}}}
function leaveDesktopRoom(){hostRequest++;nativeBusy=false;inviteBase='';if(desktopHosting())void window.arenaDesktop!.leaveRoom!().catch(e=>notice(e.message));}
