 const arcadeEvent=[...state.events].reverse().find(e=>e.type.startsWith('arcade-')&&e.source===id&&e.message&&state.time-e.time<.6&&['arcade-hit','arcade-move','arcade-parry'].includes(e.type));if(arcadeEvent&&state.phase==='fight')html+=`<div class="arcade-callout ${arcadeEvent.message?.includes('SHINKU')?'super':''}"><strong>${escape(arcadeEvent.message)}</strong>${arcadeEvent.type==='arcade-hit'?`<span>${arcadeEvent.amount||1} HIT</span>`:''}</div>`;
