 const proc=[...state.events].reverse().find(e=>e.type==='blockProc'&&e.source===id&&state.time>=e.time&&state.time-e.time<1.25);if(proc&&state.phase==='fight')html+=`<div class="block-proc-feedback" role="status" style="opacity:${Math.min(1,(1.25-(state.time-proc.time))/.3)}"><strong>BLOCK ACTIVATED</strong><span>${Object.keys(proc.mods||{}).map(cid=>escape(CHIPS.find(c=>c.id===cid)?.name||'')).filter(Boolean).join(' · ')}</span></div>`;
